import sys,re,zipfile; sys.path.insert(0,r'D:\repository\数据湖')
from pathlib import Path
from cnequity.storage.lifecycle import LifecycleStore
ROOT=Path(r'D:\repository\数据湖')
store=LifecycleStore(ROOT/'data/cnequity/meta')
objs={o['revision_id']:o for o in store.inspect(keep=2)['objects']}
targets=['d27bc73225','132ff52bd6','c8794e7dbc','74ab2d1d22','b2ff3edc6f','849564a6e6','761f8caf5b','d1fe017c28','bf5cfbda3d','f6c06a737e','87e30079c5','03e0ecb18b','f84c67d27d']
full_ids=[rid for rid in objs if any(rid.startswith(t) for t in targets)]
tokens=set(full_ids)
print('匹配',len(full_ids),'个对象; 均非current:', all(not objs[r].get('current') for r in full_ids))
hits={}
for root in [ROOT/'分析产出', ROOT/'configs']:
    for p in root.rglob('*'):
        if p.is_file() and p.suffix in ('.md','.py','.json','.csv','.txt'):
            try: txt=p.read_text(encoding='utf-8',errors='replace')
            except: continue
            f=set(re.findall(r'\b[0-9a-f]{32}\b',txt))&tokens
            if f: hits[str(p.relative_to(ROOT))]=list(f)
print('现存分析产出/configs 文件引用:', hits if hits else '无（安全）')
zh=0
for z in (ROOT/'分析产出').glob('*.zip'):
    with zipfile.ZipFile(z) as zf:
        for nm in zf.namelist():
            if Path(nm).suffix in ('.md','.py','.json','.csv','.txt'):
                f=set(re.findall(r'\b[0-9a-f]{32}\b',zf.read(nm).decode('utf-8',errors='replace')))&tokens
                if f: print('ZIP引用:',z.name,nm,f); zh+=1
print('zip引用数:',zh)
"@ 2>&1

